GATES = ['gate_1_compile', 'gate_2_test', 'gate_3_review', 'gate_4_security', 'gate_5_deploy']

def run_pqc(task, max_retries_per_gate=2):
    code = llm_generate(task)
    state = {'attempts': {}}  # IN-MEMORY ONLY

    for gate in GATES:
        for attempt in range(max_retries_per_gate):
            if gate == 'gate_1_compile':
                passed, msg = check_compile(code)
            elif gate == 'gate_2_test':
                passed, msg = check_pytest(code)  # VERIFICATION
            elif gate == 'gate_3_review':
                passed, msg = llm_review(code)  # LLM-AS-VERIFIER
            elif gate == 'gate_4_security':
                passed, msg = llm_security(code)
            elif gate == 'gate_5_deploy':
                passed, msg = check_deploy(code)
            if passed:
                break
            code = llm_fix(code, msg)  # FEEDBACK LOOP
            state['attempts'][gate] = state['attempts'].get(gate, 0) + 1
    return code, state

# G2 / G3 / G4 / G5 are all verifiers (maker/checker)
# NO schedule (single run, human triggers)
# NO cross-run state (state lost)
# NO human oversight (autonomous gates)
# NO budget (no max_cost / max_token)
# NO parallel (sequential gates)
